#include <stdio.h>
int main(void){
    // 两个输入和它们的和都用 64 位有符号整数保存。
    long long a,b;
    // 一次读入两个整数；读入失败时不使用未初始化的数据。
    if(scanf("%lld%lld",&a,&b)!=2)return 2;
    // 加法直接得到答案，按 long long 的格式只输出结果。
    printf("%lld\n",a+b);
    return 0;
}

