import java.util.*;
public class Main {
    public static void main(String[]args){
        // 从标准输入按空白分隔读取题目给出的两个数。
        Scanner s=new Scanner(System.in);
        // long 能容纳两个输入以及相加后的结果。
        long a=s.nextLong(),b=s.nextLong();
        // 整数加法就是题目所求；打印答案并换行。
        System.out.println(a+b);
    }
}

STDIO.rust:
use std::io::{
    self,Read
}
;
fn main(){
    // 读取输入文本，随后按空白分隔提取两个整数。
    let mut s=String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    // 用 i64 保存两个数，a[0]、a[1] 分别对应输入顺序。
    let a:Vec<i64>=s.split_whitespace().map(|x|x.parse().unwrap()).collect();
    // 直接计算整数和，再只输出这一个结果。
    println!("{}",a[0]+a[1]);
}
